<script setup>defineProps({ modelValue:String, searchResults:Array }); defineEmits(['update:modelValue','navigate','select'])</script>
<template><div class="topbar"><button class="brand" aria-label="文鉴，回到阅读" @click="$emit('navigate','read')">文鉴 <span>读古文，也读世界</span></button><label class="search"><span aria-hidden="true">⌕</span><input :value="modelValue" aria-label="搜索篇目、作者或原文" placeholder="搜索篇目、作者、原文……" @input="$emit('update:modelValue',$event.target.value)" @keydown.esc="$emit('update:modelValue','')" /><button v-if="modelValue" aria-label="清空搜索" @click="$emit('update:modelValue','')">×</button></label><div v-if="modelValue.trim()" class="search-results" aria-label="搜索结果"><button v-for="a in searchResults" :key="a.id" @click="$emit('select',a)"><b>{{ a.title }}</b><span>{{ a.author }}</span></button><p v-if="!searchResults?.length">没有匹配的篇目</p></div><nav aria-label="主导航"><button class="nav-read" @click="$emit('navigate','read')">阅读</button><button @click="$emit('navigate','notes')">笔记</button><button class="nav-explore" @click="$emit('navigate','explore')">探索</button><button aria-label="阅读设置" title="阅读设置" @click="$emit('navigate','settings')">⚙</button></nav></div></template>
